//! Types shared by the triage strategies and the eval harness.
//!
//! Every strategy takes a [`TriageRequest`] and returns a [`TriageResponse`].
//! The request's `config` is strategy-specific (see [`config`]); the rest is
//! the same for every strategy, so they can be compared on equal terms.
//!
//! The JSON schema of these types ([`schema::schemas`]) is generated by the
//! `triage-schema` binary into `schema/`, where the Python harness reads it;
//! a test checks that the committed files are up to date.

pub mod config;
mod hash;
mod price;
mod request;
pub mod schema;
mod triage;
mod usage;

pub use hash::config_hash;
pub use price::{Price, price};
pub use request::{Issue, Label, Repo, TriageRequest};
pub use triage::{
    Field, Kind, QUALITY_RUBRIC, ReproItem, Reproducibility, Scope, Severity, Triage,
    TriageResponse,
};
pub use usage::Usage;
